(()=>{
 const esc=M.esc,math=body=>'<math display="block">'+body+'</math>',t=s=>'<mtext>'+esc(s)+'</mtext>',frac=(a,b)=>'<mfrac>'+t(a)+t(b)+'</mfrac>';
 function equationParts(value){const powers=[...value.matchAll(/([a-zA-Z])\^\(([^()]*)\)|([a-zA-Z])\^([a-zA-Z])/g)];if(powers.length){let html='',last=0;for(const m of powers){html+=equationParts(value.slice(last,m.index))+'<msup>'+t(m[1]||m[3])+'<mrow>'+equationParts(m[2]||m[4])+'</mrow></msup>';last=m.index+m[0].length;}return html+equationParts(value.slice(last));}const atom='(?:\\([^()]+\\)[⁰¹²³⁴⁵⁶⁷⁸⁹]*|[A-Za-z0-9π⁰¹²³⁴⁵⁶⁷⁸⁹]+)',pattern=new RegExp('('+atom+')/('+atom+')','g');let html='',last=0;for(const match of value.matchAll(pattern)){html+=t(value.slice(last,match.index))+frac(match[1],match[2]);last=match.index+match[0].length;}return html+t(value.slice(last));}
 const eq=s=>'<div class="math calculus-equation">'+math(s.includes('<')?s:equationParts(s))+'</div>';
 const token=(name,glyph)=>`<mi class="symbol-token" tabindex="0" role="button" data-symbol="${name}">${glyph}</mi>`;
 Object.assign(Learning.symbols,{
  calcIntegral:['∫ · integration','This symbol asks you to accumulate contributions continuously. With bounds it gives a signed number; without bounds it asks for a family of antiderivatives.'],
  calcX:['x · integration variable','Here x is the independent input. dx tells you that integration is with respect to x. In the beam examples x is a position measured from O, in metres.'],
  calcF:['f(x) · integrand','The function being accumulated. On a graph it supplies each signed rectangle height. In a force integral this can be a load intensity w(x), in N/m.'],
  calcDx:['dx · differential','The integration differential names the variable and represents an infinitesimal interval in the accumulation interpretation. It is not a separate unknown multiplier to solve for. In u-substitution, transform the differential along with the integrand.'],
  calcA:['a · lower bound','The starting value of the integration variable. In F(b) − F(a), subtract the entire antiderivative evaluated here.'],
  calcB:['b · upper bound','The ending value of the integration variable. Evaluate the entire antiderivative at b first. Reversing a and b reverses the sign.'],
  calcC:['C · arbitrary constant','For an indefinite integral, any constant differentiates to zero. +C describes every antiderivative on a connected interval. An initial condition can determine C; in a definite integral the same constant cancels.'],
  calcN:['n · exponent','In the power rule this is the exponent of x, not the number of rectangles. Increase it to n + 1 and divide by n + 1. The rule excludes n = −1. The rectangle lab uses N for rectangle count.'],
  calcU:['u · substituted variable','A temporary variable for an inner expression. Define u, find du, rewrite the entire integral in u, then either restore x or evaluate with transformed u bounds.'],
  calcDelta:['Δx · finite rectangle width','For N equal subdivisions of [a,b], Δx = (b − a)/N. A finite rectangle sum approximates the integral; the integral is its limit as the widths approach zero.']
 });
 const panel=(title,body)=>`<article class="panel"><div class="panel-heading"><h2>${title}</h2></div>${body}</article>`,p=s=>'<p>'+s+'</p>',steps=rows=>'<ol class="calculus-worked">'+rows.map(([words,...equations])=>'<li><p>'+words+'</p>'+equations.map(eq).join('')+'</li>').join('')+'</ol>',worked=(title,rows)=>panel(title,steps(rows));
 const pages=[
 {id:'calcNotation',title:'Read an integral and see accumulation',short:'1 · Symbols & accumulation',description:'Understand the notation, rectangle sums, and signed area before using rules.',practice:['notation','riemann'],body:()=>
  panel('What every part means',p('Tap an <strong>underlined symbol</strong> for its meaning in this equation.')+eq('<msubsup>'+token('calcIntegral','∫')+token('calcA','a')+token('calcB','b')+'</msubsup>'+token('calcF','f(x)')+token('calcDx','dx'))+'<dl class="calculus-glossary"><dt>∫</dt><dd>Accumulate continuously; it is an elongated “sum” symbol.</dd><dt>f(x)</dt><dd>The integrand: the signed amount per unit x being accumulated.</dd><dt>a and b</dt><dd>Start and end values of x, not graph heights.</dd><dt>dx</dt><dd>The differential: integrate with respect to x. For beam geometry its length unit is metres.</dd></dl>'+p('A finite rectangle contributes <strong>height × width = f(xᵢ*)Δx</strong>. Add rectangles, then take the limit as their widths approach zero. For continuous functions on a finite interval this defines the integral.')+eq('∫ₐᵇ f(x) dx = lim as N → ∞ of Σᵢ₌₁ᴺ f(xᵢ*) Δx')+eq(token('calcDelta','Δx')+t(' = ')+frac('b − a','N')))+
  worked('Example · two rectangles are an approximation',[[ 'Approximate ∫₀² x² dx with two right-endpoint rectangles. Split the interval evenly.','Δx = (2 − 0)/2 = 1'],['The right endpoints are 1 and 2. Evaluate the curve at those inputs.','f(1) = 1; f(2) = 4'],['Add height times width. An increasing curve makes right-endpoint rectangles overestimate.','R₂ = 1(1) + 4(1) = 5'],['The integral uses the limit, not this particular finite sum. The exact result is smaller.','∫₀² x² dx = 8/3']])+panel('Explore the rectangle sum','<label>Curve<select id="calcCurve"><option value="square">x²</option><option value="linear">x</option><option value="signed">2x − 2 · includes negative area</option></select></label><div class="position-answer-grid"><label>Rectangles N<input id="calcRectangles" type="range" min="1" max="80" value="4"></label><label>Sample point<select id="calcSample"><option value="right">Right endpoint</option><option value="left">Left endpoint</option><option value="midpoint">Midpoint</option></select></label></div><div id="calcRectanglePlot"></div><button id="calcExpandPlot">Expand graph</button><p>Axes have a fixed scale: <strong>x from 0 to 2; y from −2 to 4</strong>. Green rectangles contribute positively; pink rectangles contribute negatively. The result is signed accumulation.</p>')},
 {id:'calcAntiderivatives',title:'Reverse differentiation',short:'2 · Antiderivatives & +C',description:'Find a function whose derivative is the integrand, and check your answer.',practice:['constant'],body:()=>panel('The question integration asks',p('An <strong>antiderivative F</strong> of f satisfies <strong>F′(x) = f(x)</strong>. The capital F is a new function, not a force in this calculus equation.')+eq('If F′(x) = f(x), then ∫ f(x) dx = F(x) + C')+p('Indefinite integrals have <strong>no bounds</strong> and return a family of functions. Definite integrals have bounds and return a signed number. These are related by the Fundamental Theorem of Calculus.')+eq(t('∫ 2x dx = x² + ')+token('calcC','C')))+worked('Example · why the constant is necessary',[[ 'Differentiate several possible answers. Each has the same derivative.','d(x²)/dx = 2x','d(x² + 7)/dx = 2x','d(x² − 10)/dx = 2x'],['The original derivative cannot tell us which vertical offset was present. Include all constants.','∫ 2x dx = x² + C'],['If an initial condition says F(2) = 9, substitute to choose one member of the family.','9 = 2² + C; C = 5','F(x) = x² + 5']])+worked('Check by differentiating',[[ 'Suppose you think ∫ 6x² dx = 2x³ + C. Differentiate your proposed answer.','d(2x³ + C)/dx = 2·3x² + 0 = 6x²'],['The derivative matches the entire integrand, including its coefficient and sign. That verifies the antiderivative.']])+panel('Common mistake',p('<strong>Integration is not simply “multiply by x.”</strong> Multiplying 6x² by x gives 6x³, whose derivative is 18x². The changed exponent requires a compensating coefficient.'))},
 {id:'calcPower',title:'Use power and sum rules',short:'3 · Powers, roots & polynomials',description:'Rewrite powers, integrate each term, and keep coefficients and signs.',practice:['power','root','negative','linearity'],body:()=>panel('The power rule',eq(t('∫ ')+'<msup>'+t('x')+token('calcN','n')+'</msup>'+t(' dx = ')+frac('xⁿ⁺¹','n + 1')+t(' + C, n ≠ −1'))+p('Use this when the integrand is a <strong>constant times a power of x</strong>. Increase the exponent by one, then divide by the new exponent. Constants can be factored out; sums and differences can be integrated term by term.')+eq('∫ [a f(x) + b g(x)] dx = a ∫ f(x) dx + b ∫ g(x) dx')+p('Here a and b are <strong>constant coefficients</strong>, unlike a and b used as integration bounds elsewhere.'))+worked('Example · polynomial',[[ 'Split the polynomial while retaining signs.','∫ (6x² − 4x + 5) dx = 6∫x² dx − 4∫x dx + 5∫1 dx'],['Apply the power rule to each term. A constant is a multiple of x⁰.','6(x³/3) − 4(x²/2) + 5x + C'],['Simplify and check with a derivative.','F(x) = 2x³ − 2x² + 5x + C','F′(x) = 6x² − 4x + 5']])+worked('Example · root and negative power',[[ 'Rewrite the integrand using exponents before integrating.','√x = x^(1/2); 1/x³ = x^(−3)'],['For ∫ 3√x dx, the new exponent is 3/2. Dividing by 3/2 means multiplying by 2/3.','∫ 3x^(1/2) dx = (3 ÷ (3/2))x^(3/2) + C = 2x^(3/2) + C'],['For ∫ 6/x³ dx on an interval excluding zero, the new exponent is −2.','∫ 6x^(−3) dx = (6 ÷ (−2))x^(−2) + C = −3/x² + C']])+panel('The exception matters',p('When <strong>n = −1</strong>, n + 1 is zero. Do not divide by zero: <strong>∫ dx/x = ln|x| + C</strong> on an interval that excludes x = 0. See the logarithm lesson. Root and negative-power expressions must also be defined on the interval you use.'))},
 {id:'calcDefinite',title:'Evaluate bounds and signed area',short:'4 · Definite integrals & bounds',description:'Apply the Fundamental Theorem of Calculus, including negative and reversed limits.',practice:['bounds','signed','reverse'],body:()=>panel('Fundamental Theorem of Calculus',p('If <strong>f is continuous on [a,b]</strong> and F′ = f, the signed accumulation is:')+eq('∫ₐᵇ f(x) dx = [F(x)]ₐᵇ = F(b) − F(a)')+p('The bracket means <strong>evaluate the entire antiderivative at the upper bound, then subtract its entire value at the lower bound</strong>. Parentheses protect signs. There is no arbitrary +C in the final numerical answer because the constants cancel.'))+worked('Example · a nonzero lower bound',[[ 'Integrate first. The given integrand is 2x + 4.','∫₁³ (2x + 4) dx = [x² + 4x]₁³'],['Substitute the upper bound into every x.','F(3) = 3² + 4(3) = 21'],['Substitute the lower bound into every x.','F(1) = 1² + 4(1) = 5'],['Subtract the complete lower value.','Integral = 21 − 5 = 16']])+worked('Example · zero accumulation is not zero area',[[ 'For f(x) = x over [−1,1], the negative part cancels the positive part.','∫₋₁¹ x dx = [x²/2]₋₁¹ = 1/2 − 1/2 = 0'],['Geometric area is nonnegative. Integrate |f|, splitting at the zero crossing.','Area = ∫₋₁⁰ (−x) dx + ∫₀¹ x dx = 1/2 + 1/2 = 1']])+panel('Bounds and domain checks',eq('∫ᵦᵃ f(x) dx = −∫ₐᵇ f(x) dx')+eq('∫ₐᶜ f(x) dx + ∫ᶜᵇ f(x) dx = ∫ₐᵇ f(x) dx')+p('Do not apply endpoint substitution across a singularity without checking an <strong>improper integral</strong>. For example, ∫₋₁¹ 1/x dx is not an ordinary convergent improper integral; subtracting ln|1| − ln|−1| would incorrectly suggest zero.'))},
 {id:'calcSubstitution',title:'Undo the chain rule with substitution',short:'5 · u-substitution',description:'Choose u, transform dx, account for factors, and transform definite bounds.',practice:['substitution','sub-bounds'],body:()=>panel('When substitution helps',p('Look for a composite function and its inner derivative, possibly differing by a constant factor. Define <strong>u = g(x)</strong>, so <strong>du = g′(x) dx</strong>. Rewrite the <strong>entire integrand and differential</strong> in u before integrating.')+eq(t('u = g(x); ')+token('calcU','du')+t(' = g′(x) dx'))+p('The symbols du and dx track the change of variable. The relationship comes from the chain rule; it is not permission to replace x arbitrarily.'))+worked('Example · exact derivative factor',[[ 'For ∫ 2x(x² + 1)³ dx, choose the inner expression.','u = x² + 1; du = 2x dx'],['Replace both the inner expression and the matched differential. No x should remain.','∫ 2x(x² + 1)³ dx = ∫ u³ du'],['Integrate in u.','∫ u³ du = u⁴/4 + C'],['For an indefinite integral, restore x.','F(x) = (x² + 1)⁴/4 + C'],['Differentiate with the chain rule to verify both factors.','F′(x) = (1/4)·4(x² + 1)³·2x = 2x(x² + 1)³']])+worked('Example · a missing factor and changed bounds',[[ 'For ∫₀¹ x(x² + 1)² dx, the derivative is 2x but we only have x.','u = x² + 1; x dx = du/2'],['Convert the limits to the variable actually being integrated.','x = 0 ⇒ u = 1; x = 1 ⇒ u = 2'],['Carry the outside factor through every step.','(1/2)∫₁² u² du = [u³/6]₁²'],['Evaluate with the u bounds. Do not put x = 0 and 1 into a u antiderivative.','Result = (8 − 1)/6 = 7/6']])},
 {id:'calcFunctions',title:'Integrate logarithmic, exponential and trig functions',short:'6 · Logs, exponentials & trig',description:'Recognize common antiderivatives and compensate for inner derivatives.',practice:['log','exponential','trig'],body:()=>panel('A small rule table with conditions','<div class="calculus-table"><table><thead><tr><th>Integrand</th><th>Antiderivative</th><th>Condition / reminder</th></tr></thead><tbody><tr><td>1/x</td><td>ln|x| + C</td><td>x ≠ 0; stay on a connected interval avoiding zero</td></tr><tr><td>e^(kx)</td><td>'+math(frac('e^(kx)','k')+t(' + C'))+'</td><td>k is a nonzero constant</td></tr><tr><td>cos x</td><td>sin x + C</td><td>Standard derivative rules use radians</td></tr><tr><td>sin x</td><td>−cos x + C</td><td>The minus sign is required</td></tr><tr><td>cos(kx)</td><td>'+math(frac('sin(kx)','k')+t(' + C'))+'</td><td>k ≠ 0; compensate for the chain factor</td></tr></tbody></table></div>'+p('<strong>ln is the natural logarithm</strong>, base e. If k = 0 in an exponential or cosine example, simplify the constant integrand and integrate it directly.'))+worked('Example · exponential coefficient',[[ 'For ∫ 5e^(2x) dx, differentiating e^(2x) would multiply by 2. Compensate by dividing by 2.','F(x) = (5/2)e^(2x) + C'],['Differentiate to verify.','F′(x) = (5/2)·2e^(2x) = 5e^(2x)']])+worked('Example · logarithm and domain',[[ 'For ∫₁⁴ 3/x dx, factor out 3 and use the logarithm rule. This interval stays positive.','[3 ln|x|]₁⁴'],['Evaluate the endpoints. ln1 is zero.','3 ln4 − 3 ln1 = 3 ln4 ≈ 4.15888']])+worked('Example · trig sign and angle units',[[ 'Use the antiderivative of sin x. For these calculus formulas, x is in radians.','∫₀^(π/2) sin x dx = [−cos x]₀^(π/2)'],['Subtract the negative lower-bound value.','−cos(π/2) − (−cos0) = 0 + 1 = 1']])+panel('Calculator reminder',p('The study calculator defaults to <strong>degrees</strong> for statics angles. Switch it to <strong>RAD</strong> for these standard trigonometric integration examples.'))},
 {id:'calcParts',title:'Integration by parts',short:'7 · Integration by parts',description:'Reverse the product rule when substitution does not directly match.',practice:['parts'],body:()=>panel('Derive the rule from a derivative',eq('(uv)′ = u′v + uv′')+p('Integrate and rearrange the product rule:')+eq('∫ u dv = uv − ∫ v du')+p('Choose <strong>u</strong> so differentiating makes it simpler, and choose <strong>dv</strong> so you can integrate it to obtain v. This method is useful for a polynomial multiplied by an exponential or certain trig functions. It is <strong>not</strong> the rule “integrate each factor and multiply.”'))+worked('Example · ∫ x e^x dx',[[ 'Choose the polynomial to differentiate and the exponential to integrate.','u = x; du = dx','dv = e^x dx; v = e^x'],['Apply the subtraction in the parts formula.','∫ x e^x dx = x e^x − ∫ e^x dx'],['Integrate the remaining simpler function.','F(x) = x e^x − e^x + C = (x − 1)e^x + C'],['Check using the product rule, not just one factor’s derivative.','F′(x) = e^x + (x − 1)e^x = x e^x']])+panel('What this course does not require yet',p('This is an introduction to the method. Most simple Chapter 3 distributed loads use <strong>powers, linearity, bounds, and piecewise sums</strong>. More advanced techniques such as partial fractions and trigonometric substitution are not necessary for those examples.'))},
 {id:'calcStatics',title:'Turn integration into force and location',short:'8 · Apply calculus to loads',description:'Build dF and dQ, track units, and combine piecewise intervals.',practice:['load','piecewise'],body:()=>panel('What the two integrals accumulate',p('For a signed load intensity w(x), <strong>dF = w(x) dx</strong>. To measure its moment contribution about O, multiply by the position x: <strong>dQ = x w(x) dx</strong>.')+eq('FR = ∫ₐᵇ w(x) dx; Q = ∫ₐᵇ x w(x) dx')+eq(t('x̄ = ')+frac('Q','FR')+t(', FR ≠ 0'))+p('Units explain the roles: <strong>(N/m)·m = N</strong>; <strong>m·(N/m)·m = N·m</strong>; <strong>(N·m)/N = m</strong>. Q is the first moment of this scalar loading about the chosen origin; its rotational sign depends on the force direction and coordinate convention. Use consistent signs in force and moment equations.'))+worked('Example · quadratic intensity',[[ 'Let a downward magnitude be w(x) = 12x² on [0,3] m. The coefficient has units N/m³ so w has units N/m.','FR = ∫₀³ 12x² dx = [4x³]₀³ = 108 N'],['Location requires a separate integral. The extra x changes the integrand from x² to x³.','Q = ∫₀³ x(12x²) dx = [3x⁴]₀³ = 243 N·m'],['Divide using the same origin and loading interval.','x̄ = 243/108 = 2.25 m'],['Check the physics: the load is heavier toward x = 3, so its centroid should lie beyond the midpoint 1.5 m, inside the loaded interval.']])+worked('Example · piecewise intensity',[[ 'A downward load is 100 N/m on [0,2] m and 200 N/m on (2,3] m. Split the integral at the function change.','FR = ∫₀² 100 dx + ∫₂³ 200 dx = 200 + 200 = 400 N'],['Keep global x measured from O in both first-moment integrals.','Q = ∫₀² 100x dx + ∫₂³ 200x dx','Q = [50x²]₀² + [100x²]₂³ = 200 + 500 = 700 N·m'],['Combine moments before dividing by the total force.','x̄ = 700/400 = 1.75 m']])+panel('Zero force is a special case',p('Opposing signed loads may sum to <strong>FR = 0</strong> while Q remains nonzero. Do not divide by zero to locate a force: retain the equivalent <strong>pure couple</strong>.'))},
 {id:'calcPractice',title:'Practise integration by method',short:'9 · Practice library',description:'Choose a method, check each mathematical step, or read a complete worked solution.',practice:[],body:()=>panel('Choose what you want to practise',p('Each problem opens in the existing roadmap with <strong>hints, full worked examples, checked-step history, and a significant-figure selector</strong>. Algebra answers use named coefficients and exponents so checking does not depend on one particular way of typing a symbolic expression.')+p('For example, when F(x) = ax³ + bx² + cx + C, enter a, b, and c separately. The worked solution always shows the full expression. Opening hints or solutions marks that attempt as assisted. Independent completions contribute to the existing <strong>Integration</strong> mastery bar; they are not counted a second time in a separate overall topic.'))}
 ];
 const practiceButtons=ids=>'<div class="calculus-practice-links">'+ids.map(id=>{const problem=RoadmapData.problems.find(p=>p.id==='calc-'+id);return `<button data-calculus-problem="${problem.id}">${esc(problem.typeName)} →</button>`;}).join('')+'</div>';
 for(const [index,page] of pages.entries()){
  const section=document.createElement('section');section.id=page.id;section.className='view calculus-view';section.hidden=true;
  section.innerHTML=page.body()+(page.id==='calcPractice'?pages.filter(p=>p.practice.length).map(p=>panel(p.short,practiceButtons(p.practice))).join(''):panel('Practise this lesson',practiceButtons(page.practice)))+`<div class="actions"><button data-calculus-view="integralsWorkspace">Integration overview</button>${index>0?`<button data-calculus-view="${pages[index-1].id}">← Previous lesson</button>`:''}${index<pages.length-1?`<button data-calculus-view="${pages[index+1].id}">Next lesson →</button>`:''}</div>`;
  document.querySelector('main').appendChild(section);
 }
 // Keep Integration as one topic, with a folder of focused lesson pages below it.
 const entry=document.querySelector('#workspaceFolder [data-view="integralsWorkspace"]'),folder=document.createElement('details');folder.id='calculusFolder';folder.className='calculus-folder';folder.innerHTML='<summary>Integration · learn calculus</summary><div class="nav-children"><button data-calculus-view="integralsWorkspace">Overview & load lab</button>'+pages.map(page=>`<button data-calculus-view="${page.id}">${page.short}</button>`).join('')+'</div>';entry.replaceWith(folder);try{folder.open=localStorage.getItem('statics-calculus-folder')==='open';}catch{}folder.addEventListener('toggle',()=>{try{localStorage.setItem('statics-calculus-folder',folder.open?'open':'closed');}catch{}});
 const intro=document.createElement('article');intro.className='panel';intro.innerHTML='<h2>Learn integration from the beginning</h2><p>Follow the calculus lessons in order, or choose a specific rule. Each lesson explains notation, why a method works, worked examples, and guided practice.</p><div class="calculus-practice-links">'+pages.map(page=>`<button data-calculus-view="${page.id}">${page.short}</button>`).join('')+'</div>';$('integralsWorkspace').prepend(intro);
 function open(id){if(window.examInProgress)return;showView(id);folder.open=true;}
 document.querySelectorAll('[data-calculus-view]').forEach(button=>button.onclick=()=>open(button.dataset.calculusView));
 document.querySelectorAll('[data-calculus-problem]').forEach(button=>button.onclick=()=>{if(window.examInProgress)return;GuidedRoadmap.open('integrals');GuidedRoadmap.selectProblem(button.dataset.calculusProblem);});
 const oldActivate=StudyExperience.activate;StudyExperience.activate=name=>{oldActivate(name);const page=pages.find(page=>page.id===name);if(!page)return;$('pageTitle').textContent=page.title;$('pageDescription').textContent=page.description;$('pageCategory').textContent='WORKSPACE / INTEGRATION / CALCULUS';document.title=page.title+' | Statics Study Lab';document.querySelectorAll('nav [data-calculus-view]').forEach(button=>{const active=button.dataset.calculusView===name;button.classList.toggle('active',active);button.setAttribute('aria-current',active?'page':'false');});folder.open=true;};
 const fmt=n=>Number(n.toPrecision(7));
 function plotHTML(name,n,method){const result=CalculusData.riemann(name,n,method),fn=CalculusData.functions[name],sx=x=>65+230*x,sy=y=>250-45*y;let shape='';for(const r of result.rectangles)shape+=`<rect x="${sx(r.left)}" y="${sy(Math.max(0,r.height))}" width="${230*result.dx}" height="${45*Math.abs(r.height)}" fill="${r.height>=0?'#b8f477':'#d6b6ff'}" fill-opacity=".23" stroke="${r.height>=0?'#b8f477':'#d6b6ff'}" stroke-width=".8"/>`;let ticks='';for(const x of [0,.5,1,1.5,2])ticks+=`<text x="${sx(x)}" y="${sy(0)+24}" fill="#cbd7e6" text-anchor="middle">${x}</text>`;for(const y of [-2,-1,1,2,3,4])ticks+=`<text x="${sx(0)-12}" y="${sy(y)+5}" fill="#cbd7e6" text-anchor="end">${y}</text>`;const path=Array.from({length:101},(_,i)=>{const x=2*i/100;return (i?'L':'M')+sx(x)+' '+sy(fn.f(x));}).join(' ');return `<svg viewBox="0 0 600 400" role="img" aria-label="${n} ${method} rectangles under ${esc(fn.label)} from zero to two"><rect width="600" height="400" fill="#141b24"/>${shape}<path d="M65 50V340M65 250H545" stroke="#8a9caf" fill="none"/>${ticks}<path d="${path}" fill="none" stroke="#8cbcff" stroke-width="3"/><text x="535" y="235" fill="#dce5ef">x</text><text x="33" y="45" fill="#dce5ef">y</text><text x="85" y="32" fill="#8cbcff">f(x) = ${esc(fn.label)} · fixed axis scale</text><text x="65" y="380" fill="#dce5ef">${n} rectangles; Δx = ${fmt(result.dx)}</text></svg><div class="insight" role="status"><p><strong>Rectangle sum:</strong> ${fmt(result.approx)} · <strong>Exact integral:</strong> ${fmt(result.exact)}</p><p><strong>Signed error (sum − exact):</strong> ${fmt(result.approx-result.exact)}</p></div>`;}
 function update(){const name=$('calcCurve').value,n=Number($('calcRectangles').value),method=$('calcSample').value;$('calcRectanglePlot').innerHTML=plotHTML(name,n,method);}
 ['calcCurve','calcRectangles','calcSample'].forEach(id=>$(id).addEventListener('input',update));update();
 const dialog=document.createElement('dialog');dialog.id='calculusPlotDialog';dialog.className='calculus-plot-dialog';dialog.setAttribute('aria-label','Expanded rectangle-sum graph');document.body.appendChild(dialog);$('calcExpandPlot').onclick=()=>{dialog.innerHTML='<button id="closeCalculusPlot" aria-label="Close expanded graph">Close graph ×</button>'+plotHTML($('calcCurve').value,Number($('calcRectangles').value),$('calcSample').value);$('closeCalculusPlot').onclick=()=>dialog.close();dialog.showModal();};
 // Reuse the update notice and let returning users see what this release added.
 const splash=$('updateSplash');splash.querySelector('p').textContent='Integration now includes nine focused calculus pages, clickable notation, a rectangle-sum visualizer, and 18 new guided problems with full worked solutions.';
 window.CalculusLessons={pages,open,plotHTML,equationParts};
})();
